#include <openssl/aes.h>
#include <openssl/sha.h>
#include <openssl/bn.h>
#include <string.h>

#if defined(__SYMBIAN32__)
_Static_assert(sizeof(BN_ULONG) == 4 && BN_BITS2 == 32,
               "OpenSSL bignum limbs must match the guest ABI");
#endif

int SymbianOpenSslKnownAnswers(void) {
  const unsigned char key[16] = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
                                 0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f};
  const unsigned char plain[16] = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77,
                                   0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff};
  unsigned char cipher[16] = {0x69, 0xc4, 0xe0, 0xd8, 0x6a, 0x7b, 0x04, 0x30,
                              0xd8, 0xcd, 0xb7, 0x80, 0x70, 0xb4, 0xc5, 0x5a};
  const unsigned char digest[32] = {
      0xba, 0x78, 0x16, 0xbf, 0x8f, 0x01, 0xcf, 0xea, 0x41, 0x41, 0x40,
      0xde, 0x5d, 0xae, 0x22, 0x23, 0xb0, 0x03, 0x61, 0xa3, 0x96, 0x17,
      0x7a, 0x9c, 0xb4, 0x10, 0xff, 0x61, 0xf2, 0x00, 0x15, 0xad};
#ifdef SYMBIAN_MBEDTLS_CHANGED_VECTOR
  cipher[0] ^= 1;
#endif
  unsigned char output[32];
  AES_KEY aes;
  if (AES_set_encrypt_key(key, 128, &aes) != 0) return -123;
  AES_encrypt(plain, output, &aes);
  if (memcmp(output, cipher, sizeof(cipher)) != 0) return -123;
  SHA256_CTX sha;
  if (!SHA256_Init(&sha) || !SHA256_Update(&sha, "abc", 3) ||
      !SHA256_Final(output, &sha) ||
      memcmp(output, digest, sizeof(digest)) != 0) return -124;
  return 0;
}
